import "dotenv/config";
import express from "express";
import path from "path";
import fs from "fs";
import net from "net";
import { createServer as createViteServer } from "vite";
import { createClient } from "@supabase/supabase-js";

async function startServer() {
  const app = express();
  const requestedPort = parseInt(process.env.PORT ?? "3000", 10);
  const requestedHmrPort = parseInt(process.env.HMR_PORT ?? "24678", 10);

  async function isPortFree(port: number) {
    return new Promise<boolean>((resolve) => {
      const tester = net.createServer()
        .once("error", () => resolve(false))
        .once("listening", () => tester.close(() => resolve(true)))
        .listen(port, "127.0.0.1");
    });
  }

  async function findAvailablePort(startPort: number, maxAttempts = 20) {
    let port = startPort;
    for (let i = 0; i < maxAttempts; i += 1) {
      if (await isPortFree(port)) {
        return port;
      }
      port += 1;
    }
    throw new Error(`No available port found in range ${startPort}-${startPort + maxAttempts - 1}`);
  }

  const PORT = await findAvailablePort(requestedPort);
  const HMR_PORT = await findAvailablePort(requestedHmrPort);

  if (PORT !== requestedPort) {
    console.warn(`Port ${requestedPort} is already in use. Starting on ${PORT} instead.`);
  }
  if (HMR_PORT !== requestedHmrPort) {
    console.warn(`HMR port ${requestedHmrPort} is already in use. Using ${HMR_PORT} instead.`);
  }

  app.use(express.json());

  const configPath = path.join(process.cwd(), "src", "theme-config.json");
  const localMessagesPath = path.join(process.cwd(), "src", "local_messages.json");
  const localBlogsPath = path.join(process.cwd(), "src", "dynamic_blogs.json");
  const localTestimonialsPath = path.join(process.cwd(), "src", "dynamic_testimonials.json");
  const localProjectsPath = path.join(process.cwd(), "src", "dynamic_projects.json");
  const localProjectsIndexPath = path.join(process.cwd(), "src", "dynamic_projects_index.json");
  const localProjectsLayoutPath = path.join(process.cwd(), "src", "dynamic_projects_layout.json");

  // Lazy-initialized Supabase Client to prevent crashes when keys are not configured
  let supabaseClient: any = null;

  function getSupabase() {
    if (!supabaseClient) {
      const supabaseUrl = process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL;
      const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_ROLE_KEY;
      const anonKey = process.env.SUPABASE_ANON_KEY || process.env.VITE_SUPABASE_PUBLISHABLE_KEY;
      const effectiveKey = serviceRoleKey || anonKey;

      if (supabaseUrl && effectiveKey) {
        supabaseClient = createClient(supabaseUrl, effectiveKey, {
          auth: { persistSession: false, autoRefreshToken: false }
        });
      }
    }
    return supabaseClient;
  }

  // Backup message helper when Supabase is not yet configured or is offline
  async function saveMessageLocally(payload: any) {
    try {
      let messages = [];
      if (fs.existsSync(localMessagesPath)) {
        const data = await fs.promises.readFile(localMessagesPath, "utf-8");
        try {
          messages = JSON.parse(data);
          if (!Array.isArray(messages)) messages = [];
        } catch (e) {
          messages = [];
        }
      }
      messages.unshift(payload); // Newest messages first
      await fs.promises.writeFile(localMessagesPath, JSON.stringify(messages, null, 2), "utf-8");
    } catch (err) {
      console.error("Local message logging error:", err);
    }
  }

  // Local blogs helper functions
  async function readLocalBlogs() {
    try {
      if (fs.existsSync(localBlogsPath)) {
        const data = await fs.promises.readFile(localBlogsPath, "utf-8");
        const parsed = JSON.parse(data);
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch (e) {
      console.error("Error reading local blogs, returning empty list:", e);
    }
    return [];
  }

  async function saveBlogLocally(blog: any) {
    try {
      const blogs = await readLocalBlogs();
      blogs.unshift(blog); // Newest first
      await fs.promises.writeFile(localBlogsPath, JSON.stringify(blogs, null, 2), "utf-8");
    } catch (err) {
      console.error("Local blog saving error:", err);
    }
  }

  async function updateBlogLocally(id: string, updatedFields: any) {
    try {
      const blogs = await readLocalBlogs();
      const index = blogs.findIndex((b: any) => b.id === id);
      if (index !== -1) {
        blogs[index] = { ...blogs[index], ...updatedFields };
        await fs.promises.writeFile(localBlogsPath, JSON.stringify(blogs, null, 2), "utf-8");
        return true;
      }
    } catch (err) {
      console.error("Local blog updating error:", err);
    }
    return false;
  }

  async function deleteBlogLocally(id: string) {
    try {
      const blogs = await readLocalBlogs();
      const filtered = blogs.filter((b: any) => b.id !== id);
      await fs.promises.writeFile(localBlogsPath, JSON.stringify(filtered, null, 2), "utf-8");
      return true;
    } catch (err) {
      console.error("Local blog deleting error:", err);
    }
    return false;
  }

  async function readLocalTestimonials(): Promise<any[]> {
    try {
      if (fs.existsSync(localTestimonialsPath)) {
        const parsed = JSON.parse(await fs.promises.readFile(localTestimonialsPath, "utf-8"));
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch (err) {
      console.error("Error reading local testimonials:", err);
    }
    return [];
  }

  async function writeLocalTestimonials(testimonials: any[]) {
    await fs.promises.writeFile(localTestimonialsPath, JSON.stringify(testimonials, null, 2), "utf-8");
  }

  async function readLocalProjects(): Promise<Record<string, any>> {
    try {
      if (fs.existsSync(localProjectsPath)) {
        const data = await fs.promises.readFile(localProjectsPath, "utf-8");
        const parsed = JSON.parse(data);
        if (Array.isArray(parsed)) {
          return Object.fromEntries(parsed.filter((project) => project && project.id).map((project) => [project.id, project]));
        }
        if (parsed && typeof parsed === "object") {
          const { _order: _storedOrder, ...projects } = parsed;
          return projects;
        }
        return {};
      }
    } catch (e) {
      console.error("Error reading local projects, returning empty map:", e);
    }
    return {};
  }

  async function writeLocalProjects(projects: Record<string, any>) {
    const currentData = fs.existsSync(localProjectsPath) ? JSON.parse(await fs.promises.readFile(localProjectsPath, "utf-8")) : {};
    const storedOrder = Array.isArray(currentData?._order) ? currentData._order : [];
    await fs.promises.writeFile(localProjectsPath, JSON.stringify({ _order: storedOrder, ...projects }, null, 2), "utf-8");
  }

  async function readLocalProjectOrder(): Promise<string[]> {
    try {
      if (fs.existsSync(localProjectsPath)) {
        const parsed = JSON.parse(await fs.promises.readFile(localProjectsPath, "utf-8"));
        return Array.isArray(parsed?._order) ? parsed._order.filter((id: unknown): id is string => typeof id === "string") : [];
      }
    } catch (err) {
      console.error("Error reading local project order:", err);
    }
    return [];
  }

  async function writeLocalProjectOrder(order: string[]) {
    const projects = await readLocalProjects();
    await fs.promises.writeFile(localProjectsPath, JSON.stringify({ _order: order, ...projects }, null, 2), "utf-8");
  }

  async function readLocalProjectLayout(): Promise<Record<string, { width: number; height: number }>> {
    try {
      if (fs.existsSync(localProjectsLayoutPath)) {
        const parsed = JSON.parse(await fs.promises.readFile(localProjectsLayoutPath, "utf-8"));
        return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
      }
    } catch (err) {
      console.error("Error reading local project layout:", err);
    }
    return {};
  }

  async function writeLocalProjectLayout(layout: Record<string, { width: number; height: number }>) {
    await fs.promises.writeFile(localProjectsLayoutPath, JSON.stringify(layout, null, 2), "utf-8");
  }

  async function readLocalProjectIndex(): Promise<string[] | null> {
    try {
      if (!fs.existsSync(localProjectsIndexPath)) return null;
      const parsed = JSON.parse(await fs.promises.readFile(localProjectsIndexPath, "utf-8"));
      return Array.isArray(parsed?.ids) ? parsed.ids.filter((id: unknown): id is string => typeof id === "string") : null;
    } catch (err) {
      console.error("Error reading local project index:", err);
      return null;
    }
  }

  async function writeLocalProjectIndex(ids: string[]) {
    await fs.promises.writeFile(localProjectsIndexPath, JSON.stringify({ ids }, null, 2), "utf-8");
  }

  // API Route: Get saved configuration
  app.get("/api/config", async (req, res) => {
    try {
      if (fs.existsSync(configPath)) {
        const data = await fs.promises.readFile(configPath, "utf-8");
        return res.json(JSON.parse(data));
      }
      return res.json({
        themeColor: "#D4AF37",
        renderMode: "constellation"
      });
    } catch (err) {
      console.error("Error reading theme config:", err);
      return res.json({
        themeColor: "#D4AF37",
        renderMode: "constellation"
      });
    }
  });

  // API Route: Save configuration
  app.post("/api/config", async (req, res) => {
    try {
      const { themeColor, renderMode } = req.body;
      const newConfig = {
        themeColor: themeColor || "#D4AF37",
        renderMode: renderMode || "constellation"
      };

      const dir = path.dirname(configPath);
      if (!fs.existsSync(dir)) {
        await fs.promises.mkdir(dir, { recursive: true });
      }

      await fs.promises.writeFile(configPath, JSON.stringify(newConfig, null, 2), "utf-8");
      return res.json({ success: true, config: newConfig });
    } catch (err) {
      console.error("Error saving theme config:", err);
      return res.status(500).json({ error: "Failed to save configuration" });
    }
  });

  // API Route: Submit contact/inquiry message
  app.post("/api/contact", async (req, res) => {
    try {
      const { name, email, phone, message, service } = req.body;

      if (!name || !email || !message) {
        return res.status(400).json({ error: "Missing required fields (name, email, message)" });
      }

      const payload = {
        name,
        email,
        phone: phone || null,
        message,
        service: service || "Direct Contact",
        created_at: new Date().toISOString()
      };

      const supabase = getSupabase();
      if (supabase) {
        console.log("Supabase configured. Attempting to insert message:", payload);
        const { data, error } = await supabase
          .from("contact_messages")
          .insert([payload])
          .select();

        if (error) {
          console.error("Supabase insertion error, falling back to local file:", error);
          console.error("Supabase payload that failed:", payload);
          await saveMessageLocally(payload);
          return res.status(500).json({
            success: false,
            savedLocally: true,
            message: "Stored locally. Supabase insert failed: " + error.message,
            error: error.message
          });
        }

        console.log("Supabase insert success:", data);
        return res.json({
          success: true,
          savedInSupabase: true,
          message: "Message successfully transmitted and synced to your Supabase cloud backend."
        });
      } else {
        console.log("Supabase not configured. Saving message locally.");
        await saveMessageLocally(payload);
        return res.json({
          success: true,
          savedLocally: true,
          message: "Logged locally in server workspace. Configure SUPABASE_URL and SUPABASE_ANON_KEY to sync to your live cloud database!"
        });
      }
    } catch (err: any) {
      console.error("Error in /api/contact:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  // API Route: Get dynamic blogs
  app.get("/api/blogs", async (req, res) => {
    try {
      const localBlogs = await readLocalBlogs();
      return res.json(localBlogs);
    } catch (err: any) {
      console.error("Error in GET /api/blogs:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  // API Route: Save authored blog
  app.post("/api/blogs", async (req, res) => {
    try {
      const { title, excerpt, category, readTime, tags, imageUrl, content, featured } = req.body;

      if (!title || !excerpt || !category || !content) {
        return res.status(400).json({ error: "Missing required fields (title, excerpt, category, content)" });
      }

      const id = title
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/(^-|-$)+/g, "");

      const payload = {
        id,
        title,
        excerpt,
        category,
        readTime: readTime || "3 min read",
        tags: Array.isArray(tags) ? tags : ["Dynamic"],
        imageUrl: imageUrl || "https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?q=80&w=600&auto=format&fit=crop",
        content,
        featured: !!featured,
        date: new Date().toLocaleDateString("en-US", {
          year: "numeric",
          month: "long",
          day: "numeric"
        }),
        created_at: new Date().toISOString()
      };

      await saveBlogLocally(payload);
      return res.json({
        success: true,
        savedLocally: true,
        id,
        message: "Blog post saved locally in server workspace."
      });
    } catch (err: any) {
      console.error("Error in POST /api/blogs:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  // API Route: Update blog post (Edit)
  app.put("/api/blogs/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const { title, excerpt, category, readTime, tags, imageUrl, content, featured } = req.body;

      if (!title || !excerpt || !category || !content) {
        return res.status(400).json({ error: "Missing required fields for update (title, excerpt, category, content)" });
      }

      const updatedFields = {
        title,
        excerpt,
        category,
        readTime: readTime || "3 min read",
        tags: Array.isArray(tags) ? tags : ["Dynamic"],
        imageUrl: imageUrl || "https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?q=80&w=600&auto=format&fit=crop",
        content,
        featured: !!featured,
      };

      const localSuccess = await updateBlogLocally(id, updatedFields);
      return res.json({
        success: localSuccess,
        savedLocally: true,
        id,
        message: localSuccess ? "Blog post updated locally." : "Blog post not found locally."
      });
    } catch (err: any) {
      console.error("Error in PUT /api/blogs:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  // API Route: Delete blog post (Remove)
  app.delete("/api/blogs/:id", async (req, res) => {
    try {
      const { id } = req.params;

      const localSuccess = await deleteBlogLocally(id);
      return res.json({
        success: localSuccess,
        deletedLocally: true,
        id,
        message: localSuccess ? "Blog post deleted locally." : "Blog post not found locally."
      });
    } catch (err: any) {
      console.error("Error in DELETE /api/blogs:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.get("/api/testimonials", async (_req, res) => {
    try {
      return res.json(await readLocalTestimonials());
    } catch (err: any) {
      console.error("Error in GET /api/testimonials:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.put("/api/testimonials", async (req, res) => {
    try {
      const testimonials = Array.isArray(req.body?.testimonials) ? req.body.testimonials : null;
      if (!testimonials) return res.status(400).json({ error: "A testimonials array is required." });
      const sanitizedTestimonials = testimonials.map((testimonial: any) => ({
        quote: typeof testimonial.quote === "string" ? testimonial.quote.trim() : "",
        name: typeof testimonial.name === "string" ? testimonial.name.trim() : "",
        role: typeof testimonial.role === "string" ? testimonial.role.trim() : "",
        avatar: typeof testimonial.avatar === "string" ? testimonial.avatar.trim() : ""
      })).filter((testimonial: any) => testimonial.quote && testimonial.name);
      await writeLocalTestimonials(sanitizedTestimonials);
      return res.json({ success: true, testimonials: sanitizedTestimonials });
    } catch (err: any) {
      console.error("Error in PUT /api/testimonials:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.get("/api/projects", async (_req, res) => {
    try {
      const projects = await readLocalProjects();
      return res.json({
        projects: Object.values(projects).filter(Boolean),
        deletedIds: Object.keys(projects).filter((id) => projects[id] === null),
        order: await readLocalProjectOrder(),
        layout: await readLocalProjectLayout(),
        indexIds: await readLocalProjectIndex()
      });
    } catch (err: any) {
      console.error("Error in GET /api/projects:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.post("/api/projects", async (req, res) => {
    try {
      const { title, category, imageUrl, media, featuredMediaIndex, year, galleryColumns } = req.body;
      if (!title || !category || !year || (!imageUrl && (!Array.isArray(media) || media.length === 0))) {
        return res.status(400).json({ error: "Title, category, year, and either imageUrl or media are required." });
      }

      const baseId = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)+/g, "") || "project";
      const projects = await readLocalProjects();
      const id = projects[baseId] ? `${baseId}-${Date.now()}` : baseId;
      const project = { id, title, category, imageUrl: imageUrl || undefined, year, media: Array.isArray(media) ? media : undefined, galleryColumns: galleryColumns === 2 ? 2 : 1 };
      projects[id] = project;
      await writeLocalProjects(projects);
      const order = await readLocalProjectOrder();
      await writeLocalProjectOrder([...order.filter((item) => item !== id), id]);
      return res.json({ success: true, project });
    } catch (err: any) {
      console.error("Error in POST /api/projects:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.put("/api/projects/order", async (req, res) => {
    try {
      const order = Array.isArray(req.body?.order)
        ? req.body.order.filter((id: unknown): id is string => typeof id === "string")
        : null;
      if (!order) return res.status(400).json({ error: "A project ID order array is required." });
      const layout = req.body?.layout && typeof req.body.layout === "object" ? req.body.layout : {};
      await writeLocalProjectOrder(order);
      await writeLocalProjectLayout(layout);
      return res.json({ success: true, order, layout });
    } catch (err: any) {
      console.error("Error in PUT /api/projects/order:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.put("/api/projects/index", async (req, res) => {
    try {
      const ids = Array.isArray(req.body?.ids)
        ? req.body.ids.filter((id: unknown): id is string => typeof id === "string")
        : null;
      if (!ids) return res.status(400).json({ error: "A project ID index array is required." });
      await writeLocalProjectIndex([...new Set(ids)]);
      return res.json({ success: true, indexIds: [...new Set(ids)] });
    } catch (err: any) {
      console.error("Error in PUT /api/projects/index:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.put("/api/projects/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const { title, category, imageUrl, media, featuredMediaIndex, year, galleryColumns } = req.body;
      if (!title || !category || !year || (!imageUrl && (!Array.isArray(media) || media.length === 0))) {
        return res.status(400).json({ error: "Title, category, year, and either imageUrl or media are required." });
      }

      const projects = await readLocalProjects();
      const project = { ...(projects[id] || {}), id, title, category, imageUrl: imageUrl || undefined, year, media: Array.isArray(media) ? media : undefined, featuredMediaIndex: Number.isInteger(featuredMediaIndex) && featuredMediaIndex >= 0 ? featuredMediaIndex : undefined, galleryColumns: galleryColumns === 2 ? 2 : 1 };
      projects[id] = project;
      await writeLocalProjects(projects);
      return res.json({ success: true, project });
    } catch (err: any) {
      console.error("Error in PUT /api/projects:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });

  app.delete("/api/projects/:id", async (req, res) => {
    try {
      const projects = await readLocalProjects();
      const { id } = req.params;
      if (!Object.prototype.hasOwnProperty.call(projects, id)) return res.status(404).json({ error: "Project not found." });
      projects[id] = null;
      await writeLocalProjects(projects);
      await writeLocalProjectOrder((await readLocalProjectOrder()).filter((item) => item !== id));
      return res.json({ success: true, id });
    } catch (err: any) {
      console.error("Error in DELETE /api/projects:", err);
      return res.status(500).json({ error: err.message || "Internal server error" });
    }
  });


  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr: {
          port: HMR_PORT,
        },
      },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "127.0.0.1", () => {
    console.log(`Server running on http://127.0.0.1:${PORT}`);
    if (PORT !== requestedPort) {
      console.log(`Requested port ${requestedPort} was unavailable and an alternate port was selected.`);
    }
    if (HMR_PORT !== requestedHmrPort) {
      console.log(`Requested HMR port ${requestedHmrPort} was unavailable and an alternate HMR port was selected.`);
    }
  });
}

startServer();
